=> (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.kclicUsrTpId", unresolved: "session:" + "kclicUsrTpId" }; })())($c.session.getUserInfo("kclicUsrTpId"))  === 'LIST_CORP_DISCLS' && (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "odsDisclsProcsStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("odsDisclsProcsStatCd")) === '00' || ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "odsDisclsProcsStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("odsDisclsProcsStatCd")) === '30')); } }, { id: "if_wrtrptMaindocTpCd", fn: function(){ return ((dlt_disclosureContentVoArr.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "doc.wrtrptMaindocTpCd"); })()) === '1'); } }, { id: "if_mainnumber", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "mainnumber" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("mainnumber")) == 0); } }, { id: "if_wrtrptMaindocTpCd_2", fn: function(){ return ((dlt_disclosureContentVoArr.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "doc.wrtrptMaindocTpCd"); })()) === '2'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
