};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_67", entity: "dlt_disclosureContentVoArr", countIds: [], cells: [{ childId: "__rc4", fn: function (v, i) { return String(v("documentHtml")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return dlt_disclosureContentVoArr.getCellData(0, "formKorNm"); } },
        { childId: "__rb5", fn: function () { return String(String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("cautnContent"))) == null ? '' : String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("cautnContent")))).split(String.fromCharCode(10)).join('<br/>')); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.lbl_caut_span.setStyle("display", "");
        scwin.lbl_caut_span_two.setStyle("display", "none");
        scwin.caut.setStyle("display", "none");
        scwin.lbl_attach_span.setStyle("display", "");
        scwin.lbl_attach_span_two.setStyle("display", "none");
        scwin.attach.setStyle("display", "none");
        $("#txt_lblCominfo").click(function() {
                if (!$(this).hasClass('on')) {
                    $c.util.getComponent("cominfo").setStyle("display", "block");
                    scwin.cominfo.setStyle("display", "");
                    (($c.util.getComponent('txt_lblCominfo')) && ($c.util.getComponent('txt_lblCominfo')).addClass ? ($c.util.getComponent('txt_lblCominfo')).addClass('on') : console.error('[sdd] addClass 미지원 컴포넌트: txt_lblCominfo'));
                } else {
                    scwin.cominfo.setStyle("display", "none");
                    (($c.util.getComponent('txt_lblCominfo')) && ($c.util.getComponent('txt_lblCominfo')).removeClass ? ($c.util.getComponent('txt_lblCominfo')).removeClass('on') : console.error('[sdd] removeClass 미지원 컴포넌트: txt_lblCominfo'));
                }
        });
        $("#txt_lblAttach").click(function() {
                scwin.lbl_attach_span.setStyle("display", "none");
                scwin.lbl_attach_span_two.setStyle("display", "");
                scwin.attach.setStyle("display", "");
        });
        $("#txt_lblAttachTwo").click(function() {
                scwin.lbl_attach_span.setStyle("display", "");
                scwin.lbl_attach_span_two.setStyle("display", "none");
                scwin.attach.setStyle("display", "none");
        });
        $("#txt_lblCaut").click(function() {
                scwin.lbl_caut_span.setStyle("display", "none");
                scwin.lbl_caut_span_two.setStyle("display", "");
                scwin.caut.setStyle("display", "");
        });
        $("#txt_lblCautTwo").click(function() {
                scwin.lbl_caut_span.setStyle("display", "");
                scwin.lbl_caut_span_two.setStyle("display", "none");
                scwin.caut.setStyle("display", "none");
        });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70009.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fnDocumentSubmit();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @description lbl_caut_span 을(를) 보이기를 바꾼다 · lbl_caut_span_two 을(를) 보이기를 바꾼다 · caut 을(를) 보이기를 바꾼다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
        await scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods70009.onpageload' });
    }
};


